# qx_batch :: ([1, 2, 3, 4, 5, 6, 7], 3)
def qx_batch(xs, n):
    if n <= 0: return []
    return [xs[i:i+n] for i in range(0, len(xs), n)]

if __name__ == '__main__':
    print(qx_batch(([1, 2, 3, 4, 5, 6, 7], 3)))

